import{_ as p,r as n,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Loading Indicators - October CMS - 3.x","titleTemplate":false,"description":"Indicate that the page is currently loading.","frontmatter":{"subtitle":"Indicate that the page is currently loading."},"headers":[{"level":2,"title":"Progress Bar","slug":"progress-bar","link":"#progress-bar","children":[]},{"level":2,"title":"Loading Button","slug":"loading-button","link":"#loading-button","children":[]},{"level":2,"title":"Toggling Elements","slug":"toggling-elements","link":"#toggling-elements","children":[{"level":3,"title":"Detecting Global Requests","slug":"detecting-global-requests","link":"#detecting-global-requests","children":[]},{"level":3,"title":"Targeting Specific Handlers","slug":"targeting-specific-handlers","link":"#targeting-specific-handlers","children":[]}]},{"level":2,"title":"Working with JavaScript","slug":"working-with-javascript","link":"#working-with-javascript","children":[]}],"relativePath":"3.x/cms/features/loaders.md","filePath":"3.x/cms/features/loaders.md"}'),i={name:"3.x/cms/features/loaders.md"};function r(k,a,d,g,h,m){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"Loading Indicators",-1)),s(e),a[1]||(a[1]=u(`<p>When the AJAX framework makes a request to the server, it is a good idea to display a loading indicator since the page may not update immediately. There are several approaches and standard loading indicators to make it clear when an AJAX request has been triggered and is in progress.</p><h2 id="progress-bar"><a href="#progress-bar" class="header-anchor">#</a> Progress Bar</h2><p>A prominent feature of the AJAX framework is a progress bar that is displayed on the top of the page when an AJAX request runs. The progress bar listens for an AJAX request and will appear when a request takes longer than 300ms and hides again when the request is complete.</p><p>To disable the progress bar for a request, set the <code>data-request-progress-bar</code> attribute to <code>false</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDoSomething<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-progress-bar</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Do something
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>In JavaScript, set the <code>progressBar</code> option of an AJAX request to <code>false</code>.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span><span class="token function">ajax</span><span class="token punctuation">(</span><span class="token string">&#39;onSilentRequest&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">progressBar</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To disable the progress bar globally, set the <code>visibility</code> style to <code>hidden</code> using a StyleSheet.</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">.oc-progress-bar</span> <span class="token punctuation">{</span>
    <span class="token property">visibility</span><span class="token punctuation">:</span> hidden<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may display the progress bar using JavaScript using the <code>oc.progressBar</code> object and <code>show</code> / <code>hide</code> functions.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span>progressBar<span class="token punctuation">.</span><span class="token function">show</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

oc<span class="token punctuation">.</span>progressBar<span class="token punctuation">.</span><span class="token function">hide</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="loading-button"><a href="#loading-button" class="header-anchor">#</a> Loading Button</h2><p>When submitting forms, users can accidentally click the button twice and cause a double submission, and this is solved using a loading button. During AJAX requests, button elements that have the <code>data-attach-loading</code> attribute will be disabled, and a CSS class <code>oc-attach-loader</code> added. This class will spawn a loading spinner on button and anchor elements using the <code>:after</code> CSS selector.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>#<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDoSomething<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
    Do Something
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>When a button exists inside a form that contain the <code>oc-attach-loader</code> attribute will display the loading indicator.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Submit
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Since inputs do not support the <code>:after</code> CSS selector, they have a new element inserted after them instead. The element is removed once the AJAX request is complete. This is useful when working with the <code>data-track-input</code> attribute that watches the input for changes and submits the AJAX request.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>username<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onCheckUsername<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-track-input</span>
    <span class="token attr-name">data-attach-loading</span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>You can manually add the loader to a button using the <code>oc.attachLoader</code> object and <code>show</code> / <code>hide</code> functions passing the element selector or object as the first argument.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span>attachLoader<span class="token punctuation">.</span><span class="token function">show</span><span class="token punctuation">(</span><span class="token string">&#39;.my-element&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

oc<span class="token punctuation">.</span>attachLoader<span class="token punctuation">.</span><span class="token function">hide</span><span class="token punctuation">(</span><span class="token string">&#39;.my-element&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="toggling-elements"><a href="#toggling-elements" class="header-anchor">#</a> Toggling Elements</h2><p>You can use the <code>data-request-loading</code> attribute to make an element visible during an AJAX request. The value is a CSS selector that uses display <code>block</code> and <code>none</code> attributes to manage the element visibility.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onPay<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-loading</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>.is-loading<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Pay Now
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token special-attr"><span class="token attr-name">style</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value css language-css"><span class="token property">display</span><span class="token punctuation">:</span>none</span><span class="token punctuation">&quot;</span></span></span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>is-loading<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Processing Payment...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="detecting-global-requests"><a href="#detecting-global-requests" class="header-anchor">#</a> Detecting Global Requests</h3><p>You can detect when a global AJAX request is in progress by checking the <code>data-ajax-progress</code> attribute on the HTML element. Expressed in a StyleSheet as the following.</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">html[data-ajax-progress]</span> <span class="token punctuation">{</span>
    <span class="token comment">/* Display loading indicators */</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The attribute is also added to form elements.</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">form[data-ajax-progress]</span> <span class="token punctuation">{</span>
    <span class="token comment">/* The form is loading */</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="targeting-specific-handlers"><a href="#targeting-specific-handlers" class="header-anchor">#</a> Targeting Specific Handlers</h3><p>In some cases you may want to show a loading indicator for a specific <a href="./../ajax/handlers.html">AJAX handler event</a>, the <code>data-ajax-progress</code> attribute will contain the most recent handler name, and this can be used to target a specific request.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onPay<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Pay Now<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onCancel<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Cancel<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>is-payment-loading<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        Processing Payment...
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>This can be targeted using a StyleSheet attribute value selector.</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">.is-payment-loading</span> <span class="token punctuation">{</span>
    <span class="token property">display</span><span class="token punctuation">:</span> none<span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token selector">form[data-ajax-progress=onPay] .is-payment-loading</span> <span class="token punctuation">{</span>
    <span class="token property">display</span><span class="token punctuation">:</span> block<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="working-with-javascript"><a href="#working-with-javascript" class="header-anchor">#</a> Working with JavaScript</h2><p>For more complex scenarios, you can hook in to the <a href="./../ajax/javascript-api.html">AJAX JavaScript API</a> using the <code>ajax:promise</code> and <code>ajax:always</code> events. These events can be attached to the document, form or target elements.</p><div class="language-js extra-class"><pre class="language-js"><code>formElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:promise&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// A new request has started</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

formElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:always&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// A request has ended</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The following example will disable all inputs inside a form while the request is running.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:promise&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    event<span class="token punctuation">.</span>target<span class="token punctuation">.</span><span class="token function">closest</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">el</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        el<span class="token punctuation">.</span>disabled <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:always&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    event<span class="token punctuation">.</span>target<span class="token punctuation">.</span><span class="token function">closest</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">el</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        el<span class="token punctuation">.</span>disabled <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,38))])}const b=p(i,[["render",r]]);export{v as __pageData,b as default};
